function topbar(){return `<header class="app-header"><button class="brand" data-screen="home" aria-label="tripto.to Home">tripto<span class="brand-dot">.</span>to</button><div class="connection-state">${state.offline?`<span class="offline-state" role="status">${icon('info',16)} Offline</span>`:''}<button class="header-icon" data-screen="account" aria-label="Account">${icon('user',31)}</button></div></header>`;}
