function bottomNav(active){const rows=[['home','home','Home'],['trips','trips','Trip'],['add','plus','Add'],['bookings','ticket','Bookings'],['account','user','Account']];return `<nav class="bottom-nav" aria-label="Primary navigation">${rows.map(([screen,ic,label])=>screen==='add'?`<button class="nav-item nav-add" data-action="open-add" aria-label="Add trip item"><span>${icon(ic,27)}</span><small>${label}</small></button>`:`<button class="nav-item ${active===screen?'active':''}" data-screen="${screen}" ${active===screen?'aria-current="page"':''}>${icon(ic,23)}<span>${label}</span></button>`).join('')}</nav>`;}
function mobileAlert(){if(state.offline)return `<div class="mobile-alert mobile-alert--offline">${icon('info',18)}<span>Offline. Showing the last trip data saved on this phone.</span></div>`;const conflicts=Number(val(state.syncStatus,'openConflicts','open_conflicts')||0);if(conflicts)return `<div class="mobile-alert">${icon('warning',18)}<span>${conflicts} change${conflicts===1?'':'s'} need review before sync can finish.</span></div>`;return'';}
function tripContext(){if(!state.trip)return'';return `<div class="trip-context"><div class="trip-context-copy"><strong>${esc(state.trip.title||'Current trip')}</strong><span>${esc(formatTripDates(state.trip))}</span></div><span class="context-chip ${state.offline?'warning':''}">${state.offline?'Offline':'Current trip'}</span></div>`;}
function sectionHead(title,action='',label='View all'){return `<div class="section-head"><div class="section-label">${esc(title)}</div>${action?`<button class="text-action" data-action="${action}">${esc(label)}</button>`:''}</div>`;}
function activeHealthIssues(){const rows=state.health?.issues||[];return[...rows].sort((a,b)=>healthRank(a.severity)-healthRank(b.severity)||(Number(a.priority)||99)-(Number(b.priority)||99));}
function healthSummary(){const issues=activeHealthIssues();if(!issues.length)return{title:'Everything looks good',subtitle:'No known trip issues.',kind:'good',icon:'check'};const first=issues[0];return{title:`${issues.length} thing${issues.length===1?'':'s'} need attention`,subtitle:first.title||first.explanation||'Open Trip Health to review.',kind:['critical','high'].includes(first.severity)?'warning':'info',icon:'warning'};}
function nextItem(){return state.brain?.nextItem||state.timeline.filter(item=>!isCancelled(item)&&Number(val(item,'starts_at_utc','startsAtUtc'))>=Date.now()).sort((a,b)=>Number(val(a,'starts_at_utc','startsAtUtc'))-Number(val(b,'starts_at_utc','startsAtUtc')))[0]||null;}
function nextFlight(){const next=nextItem();if(!next)return null;const transport=transportForItem(itemId(next));return transport&&String(val(transport,'transport_type'))==='flight'?transport:null;}
function flightRoute(flight){return{fromCode:locationLabel(val(flight,'departure_location_id','start_location_id')),fromName:locationName(val(flight,'departure_location_id','start_location_id')),toCode:locationLabel(val(flight,'arrival_location_id','end_location_id')),toName:locationName(val(flight,'arrival_location_id','end_location_id'))};}
function flightNumber(flight){const carrier=val(flight,'marketing_airline_code','carrier_name')||'Flight',number=val(flight,'marketing_flight_number','service_number')||'';return `${carrier}${number?' '+number:''}`;}
