function timeGreeting(){const hour=new Date().getHours();return hour<12?'Good morning':hour<18?'Good afternoon':'Good evening';}function emptyTripCard(){return `<div class="empty-mobile"><div class="empty-mobile-icon">${icon('trips',31)}</div><h1>Your first trip starts here</h1><p>Create a trip, then add transport, stays and documents.</p>${primaryCta('Create a Trip','create-trip','plus')}</div>`;}
